60	static const char *TAG = "recover";
61	
62	#define EVID_DIR        AGENT_DATA_DIR "/evidence"
63	#define HEARTBEAT_FILE  EVID_DIR "/heartbeat.txt"
64	#define PID_FILE        EVID_DIR "/buggy_app.pid"
65	#define MODE_FILE       EVID_DIR "/buggy_app.mode"
66	#define ACTIONS_LOG     EVID_DIR "/actions.log"
67	#define NEEDS_HUMAN     EVID_DIR "/needs_human"
68	
69	#define RUN_ELF_PATH    "/data/ai_agent/bin/buggy_app"
70	
71	#ifndef COOLDOWN_S
72	#define COOLDOWN_S      120   /* one heartbeat period */
73	#endif
74	#define HOURLY_MAX      6
75	/* M3 recurrence watch: observe one heartbeat period after a recovery
76	 * before calling it final; a fault that comes back within it escalates.
77	 * Overridable at compile time for host tests. */
78	#ifndef RECUR_OBSERVE_S
79	#define RECUR_OBSERVE_S COOLDOWN_S
80	#endif
81	
82	/* 0=off 1=dry-run 2=confirm 3=auto; Kconfig SILOOP_RECOVERY_MODE */
83	#ifndef CONFIG_SILOOP_RECOVERY_MODE
84	#define CONFIG_SILOOP_RECOVERY_MODE 3
85	#endif
86	
87	static time_t s_last_action;
88	static time_t s_hour_start;
89	static int s_hour_count;
90	/* recovery in progress: the agent loop is single-threaded so calls are
91	 * serial in practice, but the parallel tool path can run two recover
92	 * requests from one LLM message - the second must wait its turn, not
93	 * act. */
94	static volatile int s_recovering;
95	
96	/* Fallback report state (2026-11-04 tail-failure mitigation): the LLM
97	 * call that writes report.md can fail at low heap AFTER this tool has
98	 * run, leaving the round with no written report. When the ladder ran
99	 * and no normal report followed, C code writes one from a fixed
100	 * template rendered into the static buffer at verdict time. No heap: a
101	 * rescue path must not allocate. */
102	static char s_fb_report[1024]; /* pre-rendered fallback report body */
103	static int s_fb_armed;         /* ladder ran, no report written yet */
104	
105	/* Demo unlock (nsh: recover_task reset): clear the needs_human latch
106	 * and the cooldown/rate state without rebooting the board. */
107	void tool_recover_reset(void)
108	{
109	    unlink(NEEDS_HUMAN);
110	    s_last_action = 0;
111	    s_hour_start = 0;
112	    s_hour_count = 0;
113	    s_recovering = 0;
114	}
115	
116	/* New inbound message: the previous session's recovery must not arm
117	 * the fallback for this session's LLM failures. */
118	void tool_recover_session_begin(void)
119	{
120	    s_fb_armed = 0;
121	}
122	
123	/* The normal path wrote report.md; the fallback must never overwrite
124	 * it (a later LLM failure in the same session does not mean the report
125	 * is missing). */
126	void tool_recover_report_written(void)
127	{
128	    s_fb_armed = 0;
129	}
130	
131	/* Fallback report body: exactly what the C code owns - the verdict
132	 * fields, the target, the time, one rule-derived conclusion line and
133	 * the failure marker. Rendered at verdict time into the static buffer;
134	 * the writer below only dumps it. */
135	static const char s_fb_template[] =
136	    "# Embedded Self-Diagnostic Report\n"
137	    "\n"
138	    "LLM unavailable: fallback report (written by recover_task C code\n"
139	    "because the LLM call that writes the report failed)\n"
140	    "\n"
141	    "## Recovery Record\n"
142	    "- time: %ld\n"
143	    "- target: %s\n"
144	    "- level: %d\n"
145	    "- action: %s\n"
146	    "- pre_delta: %ld\n"
147	    "- post_delta: %ld\n"
148	    "- result: %s\n"
149	    "\n"
150	    "## Conclusion\n"
151	    "- %s\n";
152	
153	static void fb_render(const char *target, int level, const char *action,
154	    long pre, long post, const char *result)
155	{
156	    const char *conclusion;
157	
158	    if (strcmp(result, "recovered") == 0 && level == 1) {
159	        /* rule: L1 recovery = a temporary stall */
160	        conclusion = "recovered after the L1 (resume) rung: a temporary "
161	            "stall; the consumer was re-enabled";
162	    } else if (strcmp(result, "recovered") == 0) {
163	        conclusion = "recovered after the L2 (restart) rung: the old "
164	            "task instance was replaced";
165	    } else {
166	        /* rule: fault present after L2 = likely code defect */
167	        conclusion = "the fault persisted through the L1/L2 ladder "
168	            "(incl. L2 restart): a code defect is likely and the "
169	            "buggy_app source needs a review";
170	    }
171	
172	    snprintf(s_fb_report, sizeof(s_fb_report), s_fb_template,
173	        (long)time(NULL), target, level, action, pre, post, result,
174	        conclusion);
175	    s_fb_armed = 1;
176	}
177	
178	/* Called by agent_loop on a terminal LLM failure. Writes report.md only
179	 * when recover_task ran this session and the normal report did not
180	 * follow. open/write/close, no stdio buffering, no heap. */
181	void tool_recover_write_fallback_report(void)
182	{
183	    if (!s_fb_armed) {
184	        return;
185	    }
186	    s_fb_armed = 0; /* one fallback report per recovery */
187	
188	    int fd = open(EVID_DIR "/report.md",
189	        O_WRONLY | O_CREAT | O_TRUNC, 0644);
190	    if (fd < 0) {
191	        syslog(LOG_ERR, "[%s] fallback report open failed (errno=%d)\n",
192	            TAG, errno);
193	        return;
194	    }
195	    size_t len = strlen(s_fb_report);
196	    ssize_t w = write(fd, s_fb_report, len);
197	    close(fd);
198	    syslog(LOG_INFO, "[%s] fallback report written (%zd/%zu bytes)\n",
199	        TAG, w, len);
200	}
201	
202	/* ── heartbeat sampling ─────────────────────────────────────────── */
203	
204	static int read_heartbeat(long *val)
205	{
206	    /* the writer truncates the file on every publish; retry past the
207	     * empty window so a healthy task is never misread as missing */
208	    for (int i = 0; i < 3; i++) {
209	        FILE *f = fopen(HEARTBEAT_FILE, "r");
210	        if (f) {
211	            int ok = (fscanf(f, "%ld", val) == 1) ? OK : ERROR;
212	            fclose(f);
213	            if (ok == OK) {
214	                return OK;
215	            }
216	        }
217	        usleep(100000);
218	    }
219	    return ERROR;
220	}
221	
222	/* Independent re-sample: delta == 0 means the monitored task stalls. */
223	static int measure_delta(long *delta)
224	{
225	    long v1, v2;
226	    if (read_heartbeat(&v1) != OK) {
227	        return ERROR;
228	    }
229	    usleep(1500000);
230	    if (read_heartbeat(&v2) != OK) {
231	        return ERROR;
232	    }
233	    *delta = v2 - v1;
234	    return OK;
235	}
236	
237	/* ── task control ───────────────────────────────────────────────── */
238	
239	static int read_pid(pid_t *pid)
240	{
241	    FILE *f = fopen(PID_FILE, "r");
242	    if (!f) {
243	        return ERROR;
244	    }
245	    int ok = (fscanf(f, "%d", pid) == 1) ? OK : ERROR;
246	    fclose(f);
247	    return ok;
248	}
249	
250	static void read_mode(char *buf, size_t size)
251	{
252	    FILE *f = fopen(MODE_FILE, "r");
253	    snprintf(buf, size, "normal");
254	    if (f) {
255	        if (!fgets(buf, (int)size, f)) {
256	            snprintf(buf, size, "normal");
257	        }
258	        fclose(f);
259	    }
260	    size_t n = strlen(buf);
261	    while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r'
262	        || buf[n - 1] == ' ')) {
263	        buf[--n] = '\0';
264	    }
265	}
266	
267	static int respawn(const char *path, const char *mode)
268	{
269	    pid_t child;
270	    char *argv[3];
271	    int rc;
272	
273	    argv[0] = (char *)"buggy_app";
274	    if (mode && strcmp(mode, "normal") != 0) {
275	        argv[1] = (char *)mode;
276	        argv[2] = NULL;
277	    } else {
278	        argv[1] = NULL;
279	    }
280	    rc = posix_spawn(&child, path, NULL, NULL, argv, NULL);
281	    if (rc != 0) {
282	        /* SiliconLoop: RUN_ELF_PATH lives on /data (tmpfs, wiped on
283	         * reboot) and nothing re-deploys it at boot, so the deployed
284	         * ELF is often missing. Fall back to the builtin registration
285	         * name so L2 restarts the same workload either way
286	         * (M3 scenario C, 2026-11-04). */
287	        rc = posix_spawn(&child, argv[0], NULL, NULL, argv, NULL);
288	    }
289	    return rc;
290	}
291	
292	/* SiliconLoop: a stale PID file whose number was reused must never make
293	 * us signal a foreign task. Verify the pid still runs a buggy_app-family
294	 * process before any kill/SIGUSR1 (M2 review item, 2026-11-03). */
295	static int verify_pid_target(pid_t pid)
296	{
297	    char path[64];
298	    snprintf(path, sizeof(path), "/proc/%d/status", (int)pid);
299	    FILE *f = fopen(path, "r");
300	    if (!f) {
301	        return ERROR;
302	    }
303	    char line[128];
304	    int ok = ERROR;
305	    while (fgets(line, sizeof(line), f)) {
306	        if (strncmp(line, "Name:", 5) == 0) {
307	            char name[32];
308	            if (sscanf(line + 5, " %31s", name) == 1
309	                && strncmp(name, "buggy_app", 9) == 0) {
310	                ok = OK;
311	            }
312	            break;
313	        }
314	    }
315	    fclose(f);
316	    return ok;
317	}
318	
319	static int stop_task(void)
320	{
321	    pid_t pid;
322	    if (read_pid(&pid) == OK) {
323	        kill(pid, SIGTERM);
324	        for (int i = 0; i < 20; i++) {
325	            if (kill(pid, 0) != 0) {
326	                break;
327	            }
328	            usleep(100000);
329	        }
330	    }
331	    return OK;
332	}
333	
334	/* ── audit + verdict ────────────────────────────────────────────── */
335	
336	static void audit(const char *target, const char *action,
337	    long pre, long post, const char *result)
338	{
339	    FILE *f = fopen(ACTIONS_LOG, "a");
340	    if (f) {
341	        fprintf(f, "%ld,%s,%s,pre=%ld,post=%ld,%s\n",
342	            (long)time(NULL), target, action, pre, post, result);
343	        fclose(f);
344	    }
345	}
346	
347	static void flag_needs_human(void)
348	{
349	    FILE *f = fopen(NEEDS_HUMAN, "w");
350	    if (f) {
351	        fprintf(f, "l3 failed\n");
352	        fclose(f);
353	    }
354	}
355	
356	/* ── one rung ───────────────────────────────────────────────────── */
357	
358	/* Returns OK when the rung executed (post_delta set), ERROR when it
359	 * could not run at all (e.g. no pid file for L1). */
360	static int rung(int level, const char *target, long *post_delta)
361	{
362	    char mode[32];
363	    read_mode(mode, sizeof(mode));
364	
365	    switch (level) {
366	    case 0: { /* L1 resume */
367	        pid_t pid;
368	        if (read_pid(&pid) != OK) {
369	            return ERROR;
370	        }
371	        if (kill(pid, SIGUSR1) != 0) {
372	            return ERROR;
373	        }
374	        usleep(3000000);
375	        return measure_delta(post_delta);
376	    }
377	    case 1: /* L2 restart, same workload */
378	        stop_task();
379	        if (respawn(RUN_ELF_PATH, mode) != 0) {
380	            return ERROR;
381	        }
382	        usleep(6000000);
383	        return measure_delta(post_delta);
384	    default: /* L3 hotfix deferred with M4; anything above L2 is human */
385	        return ERROR;
386	    }
387	}
388	
389	/* ── tool entry ─────────────────────────────────────────────────── */
390	
391	static int tool_recover_execute_inner(const char *input_json, char *output,
392	    size_t output_size);
393	
394	int tool_recover_execute(const char *input_json, char *output,
395	    size_t output_size)
396	{
397	    /* SiliconLoop: the serial log records tool results as byte counts
398	     * only, but this verdict is the acceptance evidence for recovery
399	     * rounds and is a designed public one-liner (<=256 B). Print it in
400	     * full so every round's serial log carries it. */
401	    int rc = tool_recover_execute_inner(input_json, output, output_size);
402	    syslog(LOG_INFO, "[%s] verdict %s\n", TAG, output);
403	    return rc;
404	}
405	
406	static int tool_recover_execute_inner(const char *input_json, char *output,
407	    size_t output_size)
408	{
409	    cJSON *root = cJSON_Parse(input_json);
410	    if (!root) {
411	        snprintf(output, output_size,
412	            "{\"result\":\"refused\",\"reason\":\"bad_json\"}");
413	        return ERROR;
414	    }
415	
416	    const char *action = cJSON_GetStringValue(
417	        cJSON_GetObjectItem(root, "action"));
418	    const char *target = cJSON_GetStringValue(
419	        cJSON_GetObjectItem(root, "target"));
420	    bool confirm = cJSON_IsTrue(cJSON_GetObjectItem(root, "confirm"));
421	
422	    if (s_recovering) {
423	        snprintf(output, output_size,
424	            "{\"result\":\"refused\",\"reason\":\"busy\"}");
425	        cJSON_Delete(root);
426	        return OK;
427	    }
428	
429	    /* reset/test are human-only CLI verbs (nsh/vela CLI). They must
430	     * never be reachable through an LLM tool call - refuse explicitly. */
431	    if (action && (strcmp(action, "reset") == 0
432	        || strcmp(action, "test") == 0)) {
433	        snprintf(output, output_size,
434	            "{\"result\":\"refused\",\"reason\":\"cli_only\"}");
435	        cJSON_Delete(root);
436	        return OK;
437	    }
438	
439	    int level = -1;
440	    if (action && strcmp(action, "resume") == 0) level = 0;
441	    else if (action && strcmp(action, "restart") == 0) level = 1;
442	    if (action && strcmp(action, "hotfix") == 0) {
443	        /* M4 (ELF hotfix) is deferred; the rung above L2 is the human */
444	        snprintf(output, output_size,
445	            "{\"result\":\"refused\",\"reason\":\"m4_deferred\"}");
446	        cJSON_Delete(root);
447	        return OK;
448	    }
449	
450	    /* guard: whitelist — nsh/ai_agent/network tasks are untouchable */
451	    if (level < 0 || !target
452	        || (strcmp(target, "buggy_app") != 0
453	            && strcmp(target, "buggy_app_fixed") != 0)) {
454	        snprintf(output, output_size,
455	            "{\"result\":\"refused\",\"reason\":\"whitelist\"}");
456	        audit(target ? target : "?", action ? action : "?",
457	            -1, -1, "refused_whitelist");
458	        cJSON_Delete(root);
459	        return OK;
460	    }
461	
462	    /* guard: needs_human blocks everything until manually cleared */
463	    if (access(NEEDS_HUMAN, F_OK) == 0) {
464	        snprintf(output, output_size,
465	            "{\"result\":\"needs_human\",\"reason\":\"l3_failed\"}");
466	        cJSON_Delete(root);
467	        return OK;
468	    }
469	
470	    /* guard: mode */
471	    int mode = CONFIG_SILOOP_RECOVERY_MODE;
472	    if (mode == 0) {
473	        snprintf(output, output_size,
474	            "{\"result\":\"refused\",\"reason\":\"disabled\"}");
475	        cJSON_Delete(root);
476	        return OK;
477	    }
478	
479	    /* guard: cooldown + hourly cap */
480	    time_t now = time(NULL);
481	    if (s_last_action && now - s_last_action < COOLDOWN_S) {
482	        snprintf(output, output_size,
483	            "{\"result\":\"refused\",\"reason\":\"cooldown\"}");
484	        cJSON_Delete(root);
485	        return OK;
486	    }
487	    if (s_hour_start == 0 || now - s_hour_start >= 3600) {
488	        s_hour_start = now;
489	        s_hour_count = 0;
490	    }
491	    if (s_hour_count >= HOURLY_MAX) {
492	        snprintf(output, output_size,
493	            "{\"result\":\"refused\",\"reason\":\"rate_limit\"}");
494	        cJSON_Delete(root);
495	        return OK;
496	    }
497	
498	    /* guard: independent re-sample — never touch a healthy task */
499	    long pre_delta = -1;
500	    if (measure_delta(&pre_delta) != OK) {
501	        snprintf(output, output_size,
502	            "{\"result\":\"refused\",\"reason\":\"no_heartbeat\"}");
503	        cJSON_Delete(root);
504	        return OK;
505	    }
506	    if (pre_delta > 0) {
507	        snprintf(output, output_size,
508	            "{\"result\":\"refused\",\"reason\":\"already_healthy\"}");
509	        audit(target, action, pre_delta, pre_delta, "refused_healthy");
510	        cJSON_Delete(root);
511	        return OK;
512	    }
513	
514	    /* guard: PID identity - a stale PID file whose number was reused
515	     * must never make us signal a foreign task */
516	    {
517	        pid_t cur_pid;
518	        if (read_pid(&cur_pid) == OK
519	            && verify_pid_target(cur_pid) != OK) {
520	            snprintf(output, output_size,
521	                "{\"result\":\"refused\",\"reason\":\"pid_mismatch\"}");
522	            audit(target, action, pre_delta, -1, "pid_mismatch");
523	            cJSON_Delete(root);
524	            return OK;
525	        }
526	    }
527	
528	    /* confirm mode: first call only returns the plan */
529	    if (mode == 2 && !confirm) {
530	        snprintf(output, output_size,
531	            "{\"result\":\"needs_confirm\",\"action\":\"%s\","
532	            "\"target\":\"%s\",\"pre_delta\":%ld}",
533	            action, target, pre_delta);
534	        cJSON_Delete(root);
535	        return OK;
536	    }
537	
538	    /* dry-run: report the plan, execute nothing */
539	    if (mode == 1) {
540	        snprintf(output, output_size,
541	            "{\"result\":\"dry_run\",\"action\":\"%s\",\"target\":\"%s\","
542	            "\"pre_delta\":%ld}",
543	            action, target, pre_delta);
544	        audit(target, action, pre_delta, -1, "dry_run");
545	        cJSON_Delete(root);
546	        return OK;
547	    }
548	
549	    /* ── walk the ladder from the level the LLM proposed ─────────── */
550	    s_recovering = 1;
551	    static const char *const level_name[2] = { "resume", "restart" };
552	    long post_delta = 0;
553	    int done_level = -1;
554	    int recurred = 0;
555	
556	    for (int lv = level; lv < 2; lv++) {
557	        if (rung(lv, target, &post_delta) != OK) {
558	            /* rung could not run: try the next level */
559	            post_delta = -1;
560	            continue;
561	        }
562	        if (post_delta <= 0) {
563	            continue; /* did not recover here: walk up */
564	        }
565	        /* M3 recurrence watch: hold one heartbeat period, then sample
566	         * again. A fault that comes back inside the window is not
567	         * recovered - walk up (or escalate when the ladder is done).
568	         * Blocks the agent loop for RECUR_OBSERVE_S by design: the
569	         * verdict must not be called before the watch completes. */
570	        sleep(RECUR_OBSERVE_S);
571	        long recur_delta = 0;
572	        if (measure_delta(&recur_delta) == OK && recur_delta > 0) {
573	            done_level = lv;
574	            break;
575	        }
576	        recurred = 1;
577	        post_delta = recur_delta;
578	    }
579	
580	    if (done_level < 0) {
581	        flag_needs_human();
582	        const char *why = recurred ? "recurred" : "needs_human";
583	        snprintf(output, output_size,
584	            "{\"level\":2,\"action\":\"restart\",\"target\":\"%s\","
585	            "\"pre_delta\":%ld,\"post_delta\":%ld,\"result\":\"%s\"}",
586	            target, pre_delta, post_delta, why);
587	        audit(target, action, pre_delta, post_delta, why);
588	    } else {
589	        s_last_action = time(NULL);
590	        s_hour_count++;
591	        snprintf(output, output_size,
592	            "{\"level\":%d,\"action\":\"%s\",\"target\":\"%s\","
593	            "\"pre_delta\":%ld,\"post_delta\":%ld,\"result\":\"recovered\"}",
