1	/****************************************************************************
2	 * SiliconLoop - buggy producer/consumer demo
3	 *
4	 * Reproduces the failure class that a mock test cannot catch: a producer
5	 * that waits on a bounded FIFO with no exit condition. On real hardware
6	 * the FIFO fills up and the loop never terminates; in a mock the
7	 * "has space" predicate always returns true and the test passes.
8	 *
9	 * The FIFO here is simulated in RAM so that killing it does not take the
10	 * console down with it.
11	 *
12	 * Usage:
13	 *   buggy_app          run normally (consumer drains the FIFO)
14	 *   buggy_app stall    inject the fault (consumer stops draining)
15	 *   buggy_app bug      inject the code bug (FIFO accounting drifts)
16	 *
17	 * M2 recovery support (SiliconLoop closed loop):
18	 *   SIGUSR1  soft recovery: re-enable the consumer (L1 resume)
19	 *   PID file /data/ai_agent/evidence/buggy_app.pid  for targeted kill
20	 *   mode file /data/ai_agent/evidence/buggy_app.mode so recover_task
21	 *     can respawn the same workload on L2 (a code bug must re-manifest
22	 *     after restart so the ladder can walk L1 -> L2 -> L3)
23	 ****************************************************************************/
24	
25	#include <signal.h>
26	#include <stdio.h>
27	#include <stdlib.h>
28	#include <string.h>
29	#include <unistd.h>
30	#include <pthread.h>
31	#include <sched.h>
32	
33	#define FIFO_SIZE      64
34	#define HEARTBEAT_PATH "/data/ai_agent/evidence/heartbeat.txt"
35	#define PID_FILE       "/data/ai_agent/evidence/buggy_app.pid"
36	#define MODE_FILE      "/data/ai_agent/evidence/buggy_app.mode"
37	
38	static unsigned char g_fifo[FIFO_SIZE];
39	static int g_head;
40	static int g_tail;
41	static int g_count;
42	static volatile int g_consumer_on = 1;
43	static int g_bug; /* the code bug: the drain path never releases the count */
44	static unsigned long g_produced;
45	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
46	
47	static int fifo_has_space(void)
48	{
49	    int has;
50	
51	    pthread_mutex_lock(&g_lock);
52	    has = (g_count < FIFO_SIZE);
53	    pthread_mutex_unlock(&g_lock);
54	    return has;
55	}
56	
57	static void fifo_put(unsigned char c)
58	{
59	    pthread_mutex_lock(&g_lock);
60	    g_fifo[g_head] = c;
61	    g_head = (g_head + 1) % FIFO_SIZE;
62	    g_count++;
63	    g_produced++;
64	    pthread_mutex_unlock(&g_lock);
65	}
66	
67	/* L1 soft recovery: wake the consumer back up. The handler must be
68	 * async-signal-safe; setting a flag is. */
69	static void on_usr1(int sig)
70	{
71	    (void)sig;
72	    g_consumer_on = 1;
73	}
74	
75	static void publish_identity(const char *mode)
76	{
77	    FILE *f = fopen(PID_FILE, "w");
78	
79	    if (f) {
80	        fprintf(f, "%d\n", (int)getpid());
81	        fclose(f);
82	    }
83	    f = fopen(MODE_FILE, "w");
84	    if (f) {
85	        fprintf(f, "%s\n", mode ? mode : "normal");
86	        fclose(f);
87	    }
88	}
89	
90	static void *consumer_thread(void *arg)
91	{
92	    (void)arg;
93	
94	    for (;;) {
95	        pthread_mutex_lock(&g_lock);
96	        if (g_consumer_on && g_count > 0) {
97	            g_tail = (g_tail + 1) % FIFO_SIZE;
98	            /* The code bug ("bug" mode): the drain path forgets to
99	             * release the slot, so g_count only ever grows. The FIFO
100	             * reports full forever and the producer deadlocks — a fault
101	             * that survives SIGUSR1 (the consumer is already running)
102	             * and re-manifests after restart. The fix-version ELF (M4
103	             * hotfix) simply decrements here. An earlier revision put
104	             * the bug in fifo_put (+2 per put) instead; scenario C
105	             * (m3-C.r1, 2026-11-04) proved that variant inert — with
106	             * the drain still decrementing, the count oscillates near
107	             * full and the producer is only throttled, never stuck. */
108	            g_count -= g_bug ? 0 : 1;
109	        }
110	        pthread_mutex_unlock(&g_lock);
111	        usleep(20000);
112	    }
113	
114	    return NULL;
115	}
116	
117	static void write_heartbeat(void)
118	{
119	    FILE *f = fopen(HEARTBEAT_PATH, "w");
120	
121	    if (f) {
122	        fprintf(f, "%lu\n", g_produced);
123	        fclose(f);
124	    }
125	}
