127	static void dump_pmp(void)
128	{
129	    unsigned long cfg[4];
130	    unsigned long addr[16];
131	    int i;
132	
133	    __asm__ __volatile__("csrr %0, 0x3a0" : "=r"(cfg[0]));
134	    __asm__ __volatile__("csrr %0, 0x3a1" : "=r"(cfg[1]));
135	    __asm__ __volatile__("csrr %0, 0x3a2" : "=r"(cfg[2]));
136	    __asm__ __volatile__("csrr %0, 0x3a3" : "=r"(cfg[3]));
137	
138	    __asm__ __volatile__("csrr %0, 0x3b0" : "=r"(addr[0]));
139	    __asm__ __volatile__("csrr %0, 0x3b1" : "=r"(addr[1]));
140	    __asm__ __volatile__("csrr %0, 0x3b2" : "=r"(addr[2]));
141	    __asm__ __volatile__("csrr %0, 0x3b3" : "=r"(addr[3]));
142	    __asm__ __volatile__("csrr %0, 0x3b4" : "=r"(addr[4]));
143	    __asm__ __volatile__("csrr %0, 0x3b5" : "=r"(addr[5]));
144	    __asm__ __volatile__("csrr %0, 0x3b6" : "=r"(addr[6]));
145	    __asm__ __volatile__("csrr %0, 0x3b7" : "=r"(addr[7]));
146	    __asm__ __volatile__("csrr %0, 0x3b8" : "=r"(addr[8]));
147	    __asm__ __volatile__("csrr %0, 0x3b9" : "=r"(addr[9]));
148	    __asm__ __volatile__("csrr %0, 0x3ba" : "=r"(addr[10]));
149	    __asm__ __volatile__("csrr %0, 0x3bb" : "=r"(addr[11]));
150	    __asm__ __volatile__("csrr %0, 0x3bc" : "=r"(addr[12]));
151	    __asm__ __volatile__("csrr %0, 0x3bd" : "=r"(addr[13]));
152	    __asm__ __volatile__("csrr %0, 0x3be" : "=r"(addr[14]));
153	    __asm__ __volatile__("csrr %0, 0x3bf" : "=r"(addr[15]));
154	
155	    for (i = 0; i < 16; i++) {
156	        unsigned c = (unsigned)((cfg[i / 4] >> ((i % 4) * 8)) & 0xff);
157	        printf("PMP%02d cfg=%02x R%d W%d X%d A%d L%d addr=%08lx top=%08lx\n",
158	               i, c,
159	               (c >> 0) & 1, (c >> 1) & 1, (c >> 2) & 1,
160	               (c >> 3) & 3, (c >> 7) & 1,
161	               addr[i], addr[i] << 2);
162	    }
163	}
