165	int main(int argc, char *argv[])
166	{
167	    pthread_t tid;
168	
169	    if (argc > 1 && strcmp(argv[1], "pmp") == 0) {
170	        dump_pmp();
171	        return 0;
172	    }
173	
174	    if (argc > 2 && strcmp(argv[1], "md") == 0) {
175	        unsigned long a = strtoul(argv[2], NULL, 0);
176	        const unsigned char *p = (const unsigned char *)a;
177	        int i;
178	
179	        printf("%08lx:", a);
180	        for (i = 0; i < 32; i++) {
181	            printf(" %02x", p[i]);
182	            if ((i % 16) == 15 && i != 31) {
183	                printf("\n%08lx:", a + i + 1);
184	            }
185	        }
186	        printf("\n");
187	        return 0;
188	    }
189	
190	    /* Run below the agent so a spinning producer cannot starve the
191	     * diagnostic path. The scheduler class stays SCHED_RR.
192	     */
193	    {
194	        struct sched_param sp;
195	
196	        if (sched_getparam(0, &sp) == 0) {
197	            sp.sched_priority = 50;
198	            sched_setparam(0, &sp);
199	        }
200	    }
201	
202	    if (argc > 1 && strcmp(argv[1], "stall") == 0) {
203	        g_consumer_on = 0;
204	        printf("buggy_app: consumer disabled, FIFO will fill up\n");
205	    }
206	
207	    if (argc > 1 && strcmp(argv[1], "bug") == 0) {
208	        g_bug = 1;
209	        printf("buggy_app: code bug active, FIFO count will never drain\n");
210	    }
211	
212	    /* L1 soft-recovery hook: recover_task sends SIGUSR1 to re-enable
213	     * the consumer. Also publish pid + mode so recover_task can target
214	     * exactly this task and respawn the same workload on L2. */
215	    signal(SIGUSR1, on_usr1);
216	    publish_identity(argc > 1 ? argv[1] : "normal");
217	
218	    pthread_create(&tid, NULL, consumer_thread, NULL);
219	
220	    printf("buggy_app: producing, heartbeat at %s\n", HEARTBEAT_PATH);
221	
222	    /* Wait for the agent to create the evidence directory, then publish
223	     * one heartbeat before the FIFO can fill. Without this the stalled
224	     * run leaves no heartbeat at all, and "file missing" is weaker
225	     * evidence than "value never changed".
226	     */
227	    {
228	        int tries;
229	
230	        for (tries = 0; tries < 300; tries++) {
231	            FILE *probe = fopen(HEARTBEAT_PATH, "w");
232	
233	            if (probe) {
234	                fprintf(probe, "0\n");
235	                fclose(probe);
236	                /* SiliconLoop: publish_identity() above ran before
237	                 * ai_agent had mounted /data and created the evidence
238	                 * directory, so that first attempt silently lost the
239	                 * pid/mode files. The directory is usable now - republish
240	                 * so recover_task L1/L2 has something to target. */
241	                publish_identity(argc > 1 ? argv[1] : "normal");
242	                break;
243	            }
244	
245	            sleep(1);
246	        }
247	    }
248	
249	    for (;;) {
250	        /* The bug: no exit condition, no timeout, no error path.
251	         * The usleep() is a concession to demonstrability, not part of
252	         * the fault. A bare spin here starves every lower-priority
253	         * thread on this single-core board, including the agent's own
254	         * CLI, so the diagnostic system never gets to run. That was
255	         * reproduced first; the sleep was added afterwards so the
256	         * fault stays observable. The loop still never terminates and
257	         * the task still never makes progress.
258	         */
259	        while (!fifo_has_space())
260	            usleep(1000);
261	
262	        fifo_put((unsigned char)(g_produced & 0xff));
263	
264	        if ((g_produced % 50) == 0) {
265	            write_heartbeat();
266	        }
267	
268	        usleep(10000);
269	    }
270	
271	    return 0;
272	}
